		if (ref == null)
			ref = new Linker();

        RepoState st = RepoState.getRepoState();


        String cmp = component.getText();
        if (cmp.equals("CompilerBuiltin") || cmp.equals("AnyType") || cmp.equals("CompilerLibrary")) 
        	return;


        List<String> aliases = st.alias.get(component.getText());

    	if (aliases == null)
    		return;

